contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params choose caller (operator vs owner), amount to withdraw, claim flag and recipient
    // We cannot change msg.sender here; the test contract is the caller for c. To exercise both access branches
    // we rely on invoking functions on c that set operator/owner beforehand using onlyOwner: the constructor of c sets owner to deployer (this test deployed c),
    // so this contract is owner. We'll also allow setting operator to an arbitrary address and then use onlyOwner to change it.
    function run(address newOperator, uint256 amount, bool claim, address to) public payable {
        require(address(this) != address(0)); // trivial safety

        // Read initial observable state
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Ensure cvxPoolInfo.rewards is readable and won't revert when called later.
        // We proceed to set operator to newOperator (we are owner so allowed)
        c.setOperator(newOperator);

        // Decide caller: if newOperator == address(this), then this contract is operator; otherwise it's not.
        bool willBeOperator = (newOperator == address(this));

        // Now attempt the withdrawAndUnwrap call and catch whether it reverts.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state values that are publicly observable
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // If call reverted, it must be because caller is neither operator nor owner (onlyOperatorOrOwner). Since this contract is owner, withdraw should never revert due to access.
        // However, onlyOperatorOrOwner allows owner OR operator. This contract is owner (constructor of C set owner to deployer), so call must not revert due to access control.
        // Thus, if reverted == true then it must be due to some other reason; but a general safety rule we assert is:
        // If the call did NOT revert, then the amount of CLP tokens transferred out to `to` cannot exceed `amount`. So afterBalance >= beforeBalance - amount (with underflow avoided by using an inequality that only references non-negative values).

        if (!reverted) {
            // assert final balance is not less than beforeBalance minus amount (i.e., contract didn't lose more than amount)
            // rewrite to avoid underflow: beforeBalance >= amount implies beforeBalance - amount <= afterBalance
            // We assert: afterBalance + amount >= beforeBalance
            assert(afterBalance + amount >= beforeBalance);
        } else {
            // If reverted, we still assert that caller not operator and not owner is false (because this contract is owner), so this branch should not be reachable in correct implementation.
            // To keep the assert general but provable, require that if reverted then newOperator != address(this) AND address(this) != c.owner() would hold.
            // But c.owner() is this contract (deployer). So make a weaker universally true assertion: when reverted, at least one of caller-not-owner-or-operator is true.
            // Check observable owner and operator
            address ownerAddr = c.owner();
            address op = c.operator();
            // If reverted, then msg.sender (this) must be neither owner nor operator for the modifier to trigger. We assert that.
            assert(reverted == (address(this) != ownerAddr && address(this) != op));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
