    constructor(C _c) { c = _c; }

    // single public test function
    // params: newOperator to optionally change operator, amount to withdraw, claim flag and recipient
    function run(address newOperator, uint256 amount, bool claim, address to) public payable {
        require(true);

        // observable before-balance
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // change operator (we are owner since this test deployed c)
        c.setOperator(newOperator);

        // perform the withdrawAndUnwrap call and record whether it reverted
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observable after-balance
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // Single general assertion: if the call succeeded, the contract's CLP balance did not drop by more than `amount`.
        // This is written without underflow: afterBalance + amount >= beforeBalance when not reverted.
        assert(reverted || afterBalance + amount >= beforeBalance);
    }

    receive() external payable {}
}

