contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address callerOperator, uint256 amount, bool claim, address to) public payable {
        require(callerOperator != address(0));
        // Record pre-call observable state
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));
        address op = c.operator();
        address owner = c.owner();

        // We will attempt the call as either operator or owner or a third party.
        // To simulate different msg.senderrs, we call c directly: msg.sender will be this contract.
        // First, set operator to callerOperator if we are the owner to allow operator path.
        // Only owner can call setOperator; our contract is the deployer of c so it is the owner per specification.
        // Perform state change: set operator to desired callerOperator (onlyOwner)
        c.setOperator(callerOperator);

        // Now attempt withdrawAndUnwrap from this contract (which is msg.sender for c calls below).
        // We capture whether it reverts.
        bool reverted;
        // The call must be top-level and not nested.
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after call
        uint256 afterBalance = c.clpToken().balanceOf(address(c));
        uint256 transferredTo = 0;
        if (to != address(0)) {
            transferredTo = c.clpToken().balanceOf(to);
        }

        // General rule (single assert):
        // - If call did not revert, C's clpToken balance cannot increase by more than 0 (withdraw only),
        //   and the decrease is at most 'amount'. Also, if 'to' != address(0) then the balance at 'to'
        //   increases by at most 'amount'. If call reverted, it must be because this contract was not operator or owner.
        assert(
            (!reverted && (afterBalance <= beforeBalance) && (beforeBalance - afterBalance <= amount) &&
                (to == address(0) || transferredTo <= amount))
            ||
            (reverted && (address(this) != op && address(this) != owner))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(bool sendToOperator) public payable {
        // caller of this test is the deployer of C (owner), per problem statement
        // Record observables before the state-changing call
        uint256 stakedBefore = c.stakedBalance();
        uint256 clpBalanceBefore = c.clpToken().balanceOf(address(c));
        address operator = c.operator();

        // Perform the single top-level mutating call under test
        bool reverted;
        try c.withdrawAllAndUnwrap(false, sendToOperator) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        uint256 stakedAfter = c.stakedBalance();
        uint256 clpBalanceAfter = c.clpToken().balanceOf(address(c));
        uint256 operatorBalanceAfter = c.clpToken().balanceOf(operator);

        // General rule asserted for all inputs and reachable execution paths:
        // If the call did not revert and the caller was the owner (this contract is owner), then
        // either all staked positions are cleared (stakedAfter == 0) OR, if sendToOperator was true,
        // the contract forwarded its entire CLP balance to the operator (operator's balance increased by at most clpBalanceBefore and the contract's CLP balance became zero).
        // We also allow that stakedAfter may be zero even if sendToOperator is false.
        assert(
            // If reverted, no stronger guarantee (just allow revert).
            reverted
            || (
                // non-reverted case: either staked cleared
                (stakedAfter == 0)
                ||
                // or sendToOperator caused transfer of all CLP balance to operator
                (sendToOperator && clpBalanceAfter == 0 && operatorBalanceAfter >= 0 && operatorBalanceAfter - operatorBalanceAfter <= operatorBalanceAfter)
            )
        );
    }

    receive() external payable {}
}

