contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters:
    // - callerIsOperator: if true, the InvMutTest contract will try to act as operator by setting operator beforehand via owner (owner is deployer of C, which is InvMutTest per problem statement?)
    // But the test harness deploys a fresh C with InvMutTest as deployer, so InvMutTest is owner. We use that to set operator when desired.
    function run(bool setOperatorToThis, uint256 amount, bool claim, address to) public payable {
        require(true);

        // Precondition: amount can be any value. We will read clpToken balance before, then call withdrawAndUnwrap
        // If setOperatorToThis is true, set operator to this contract (allowed because InvMutTest is the owner of freshly deployed C)
        if (setOperatorToThis) {
            // onlyOwner function: InvMutTest is owner so this should succeed
            c.setOperator(address(this));
        }

        // Read balance before
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Try calling withdrawAndUnwrap and capture whether it reverted
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // General rule asserted:
        // - If call reverted then either caller was not operator/owner (i.e., setOperatorToThis==false) OR some external call reverted; we assert that if we did not set operator to this and this contract is not owner then it must have reverted.
        // - If call succeeded and 'to' is non-zero, then the contract's clpToken balance cannot have increased by more than 0 and should have decreased by at most 'amount'. We express that afterBalance <= beforeBalance and (beforeBalance - afterBalance) <= amount when call succeeded.

        assert(
            // Either it reverted, or the call succeeded and the token balance is non-increasing and decreased by at most 'amount'
            reverted || (afterBalance <= beforeBalance && (beforeBalance - afterBalance) <= amount)
        );
    }

    receive() external payable {}
}

