contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: callerIndicator selects whether to call as operator (0), owner (1), or other (2).
    // amount is the requested withdraw amount, claim is passed through, and to is recipient.
    function run(uint8 callerIndicator, uint256 amount, bool claim, address to) public payable {
        require(callerIndicator <= 2, "bad callerIndicator");

        // Read important before-state values accessible via public surface
        uint256 beforeClpBalance = c.clpToken().balanceOf(address(c));
        address operator = c.operator();
        address owner = c.owner();

        bool reverted = false;

        // Call withdrawAndUnwrap from this contract (msg.sender = address(this)).
        // Arrange who is operator/owner by calling setOperator or transferring ownership if allowed.
        // Only owner can call setOperator/transferOwnership, but constructor of InvMutTest cannot be owner.
        // However, we can branch: if callerIndicator==0 we try to set this contract as operator via owner's privileges.
        // Since we cannot become owner (we are not initial owner), we instead rely on the existing operator/owner.
        // We'll attempt the call directly; it should revert if msg.sender is neither operator nor owner.

        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterClpBalance = c.clpToken().balanceOf(address(c));

        // Determine expectation: if this contract's address equals operator or owner then call must not revert.
        bool isOperator = (address(this) == operator);
        bool isOwner = (address(this) == owner);

        // General rule asserted:
        // - If this contract is not operator and not owner then withdrawAndUnwrap must revert.
        // - If it is operator or owner then it must not revert AND if a non-zero `to` was provided, the amount transferred out
        //   cannot exceed the delta between before and after balances (i.e., contract balance decreased by at least the transferred amount),
        //   here we assert that when call succeeded and to != address(0) then before - after >= min(amount, before).

        // Compute safe delta without underflow in assert by using comparisons rather than subtraction inside assert.
        if (!isOperator && !isOwner) {
            // must have reverted
            assert(reverted);
        } else {
            // must not have reverted
            assert(!reverted);
            if (to != address(0)) {
                // If requested amount exceeded before balance, effective transfer is at most before balance.
                // So require that afterClpBalance + ( (amount <= beforeClpBalance) ? amount : beforeClpBalance ) <= beforeClpBalance
                // Rearranged to avoid subtraction in assert: when amount <= before, afterClpBalance <= before - amount
                if (amount <= beforeClpBalance) {
                    assert(afterClpBalance <= beforeClpBalance && beforeClpBalance - afterClpBalance >= amount);
                } else {
                    // amount > before: after balance must be <= 0 i.e. equal 0
                    assert(afterClpBalance <= beforeClpBalance && afterClpBalance == 0);
                }
            }
        }
    }

    receive() external payable {}
}

