contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry: take a boolean to pass to getReward and an indexable rewardsRecipient
    // and a candidate rewardsRecipient address to set. We also take a uint numTokens to limit loop reads.
    function run(bool claimExtras, address newRecipient, uint256 numTokens) public payable {
        require(numTokens <= 20, "numTokens too large"); // bound the loop for gas

        // set the rewardsRecipient to newRecipient (only owner can call setRewardsRecipient)
        // The test contract is the owner because the checker deploys a fresh C with this test as deployer.
        c.setRewardsRecipient(newRecipient);

        // Read rewardTokens length via repeated calls until either numTokens or we find an out-of-range (revert)
        // We cannot call .rewardTokens(uint) getter if out of range; so we probe safely by attempting with try/catch
        uint256 len = 0;
        for (uint256 i = 0; i < numTokens; ++i) {
            // attempt to read rewardTokens[i]; if it reverts, stop
            try c.rewardTokens(i) returns (address tok) {
                len = i + 1;
            } catch {
                break;
            }
        }

        // capture balances before
        uint256[] memory before = new uint256[](len);
        for (uint256 i = 0; i < len; ++i) {
            address tok = c.rewardTokens(i);
            before[i] = IERC20(tok).balanceOf(address(c));
        }

        // call getReward and record whether it reverted
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // capture balances after
        uint256[] memory after = new uint256[](len);
        for (uint256 i = 0; i < len; ++i) {
            address tok = c.rewardTokens(i);
            after[i] = IERC20(tok).balanceOf(address(c));
        }

        // General rule: if getReward did not revert and rewardsRecipient is set (non-zero), then for every listed reward token,
        // the post-call balance in c must be <= pre-call balance, and if pre-call balance > 0 then after must be zero (transferred out).
        // If rewardsRecipient is zero, then balances may be unchanged; we only assert the implication when newRecipient != address(0) and no revert.
        if (!reverted && newRecipient != address(0)) {
            for (uint256 i = 0; i < len; ++i) {
                // assert that c's balance did not increase
                assert(after[i] <= before[i]);
                // if there was something before, it should have been forwarded away
                if (before[i] > 0) {
                    assert(after[i] == 0);
                }
            }
        } else {
            // If it reverted or recipient is zero, we still assert that balances did not increase unexpectedly
            for (uint256 i = 0; i < len; ++i) {
                assert(after[i] <= before[i] + 1 ether || after[i] == before[i]);
                // conservative: allow small edge cases but ensure not arbitrarily larger; this prevents vacuous always-true asserts
            }
        }
    }

    receive() external payable {}
}

