    function run(bool callAsOperator, uint256 amount, bool claim, address to) public payable {
        require(true);

        // Capture pre-state: clp token balance of c and address(c).balance
        uint256 beforeClp = c.clpToken().balanceOf(address(c));
        uint256 beforeEth = address(c).balance;

        // Decide caller by using only allowed callers: owner (this contract deployed c so it's owner) or operator.
        // We cannot actually change msg.sender for c calls; as stated, msg.sender for calls on c is this contract.
        // So to simulate both cases, we rely on c.operator() and c.owner() being possibly equal to address(this).
        // If callAsOperator is true and this contract is not operator, the call must revert with NotOperator.
        // We'll try the call and record whether it reverted.

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterClp = c.clpToken().balanceOf(address(c));
        uint256 afterEth = address(c).balance;

        // General rule:
        // - If call succeeded, then contract's CLP balance cannot have increased (withdraw/unwrap only withdraws or transfers out).
        // - If call succeeded and `to` is non-zero, the amount transferred out to `to` cannot exceed `amount` (so contract's balance decreased by at most amount).
        // - If `to` is zero, the contract's clp balance after should be >= beforeClp - amount (i.e., not decreased by more than amount), but since we avoid underflow in assert, express as afterClp + amount >= beforeClp.

        assert(
            // If reverted, no further guarantee about balances (but we still require that if reverted it was not because balances increased unexpectedly)
            reverted || (
                // afterClp is never greater than beforeClp
                afterClp <= beforeClp
                // and the decrease is at most amount: beforeClp - afterClp <= amount -> afterClp + amount >= beforeClp
                && (afterClp + amount >= beforeClp)
                // Ether balance of c doesn't increase due to withdrawAndUnwrap (it only interacts with token), so afterEth >= beforeEth - but to be safe require it didn't increase unexpectedly
                && (afterEth <= beforeEth)
            )
        );
    }

    receive() external payable {}
}

