contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property test
    // params: callerKind (0 = neither operator nor owner, 1 = operator, 2 = owner),
    // amount to withdraw, claim flag, destination address (to)
    function run(uint8 callerKind, uint256 amount, bool claim, address to) public payable {
        require(callerKind <= 2);

        // Observe pre-call public values
        uint256 preClpBal = IERC20(address(c.clpToken())).balanceOf(address(c));
        uint256 preStaked = c.stakedBalance();

        // Decide caller: we simulate calls by using this contract as the caller.
        // The contract InvMutTest is the caller for all c calls. To test different caller roles,
        // we must rely on c's recorded operator and owner. The test will behave generally:
        // - If callerKind == 1 we try to make this contract the operator by calling setOperator via owner if possible.
        // - If callerKind == 2 we try to transfer ownership to this contract (only owner can do it).
        // We perform these setup calls but they may revert if msg.sender is not owner — wrap in try/catch.

        // Try to become operator: only owner can call setOperator. If this contract is not owner, the call will revert harmlessly.
        try c.setOperator(address(this)) {} catch {}
        // Try to become owner by transferOwnership — only current owner can do it
        try c.transferOwnership(address(this)) {} catch {}

        // Now attempt the target call and record whether it reverted
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call observe public values again
        uint256 postClpBal = IERC20(address(c.clpToken())).balanceOf(address(c));
        uint256 postStaked = c.stakedBalance();

        // General rule to assert:
        // - If this contract was neither operator nor owner (i.e., setOperator and transferOwnership both reverted earlier), then withdrawAndUnwrap must have reverted.
        // - Otherwise (we are operator or owner), the call must not decrease c's reported staked balance below zero (i.e., postStaked <= preStaked), and if the call succeeded and a non-zero `to` was provided then the contract's clp token balance decreased by at most `amount` and postClpBal + amount >= preClpBal.

        // Determine whether we successfully became operator or owner by checking c.operator() and c.owner()
        bool amOperator = (c.operator() == address(this));
        bool amOwner = (c.owner() == address(this));

        // Build the asserted condition
        // Part A: if not operator and not owner => must have reverted
        bool partA = (!amOperator && !amOwner) ? reverted : true;

        // Part B: if operator or owner => if call succeeded then postStaked <= preStaked
        bool partB = true;
        if (amOperator || amOwner) {
            if (!reverted) {
                partB = (postStaked <= preStaked);
            }
        }

        // Part C: if call succeeded and `to` != address(0) then the contract transferred up to `amount` CLP outwards,
        // so the new balance plus amount should be >= previous balance (i.e., it didn't create tokens). This avoids underflow in assert.
        bool partC = true;
        if (!reverted && to != address(0)) {
            // postClpBal + amount >= preClpBal  <=>  postClpBal >= preClpBal - amount
            // avoid underflow: compare using addition
            partC = (postClpBal + amount >= preClpBal);
        }

        assert(partA && partB && partC);
    }

    receive() external payable {}
}

